/** True when this phone is Active (code verified). */
isUnlocked(phone) {
  const user = this.findByPhone(phone);
  if (!user) return false;
  if (user.status === 'active') return true;
  return !!(user.verified_at);
},

isWaitingForCode(phone) {
  const user = this.findByPhone(phone);
  if (!user || !user.is_active) return false;
  if (user.status === 'active') return false;
  return !user.verified_at;
},

displayStatus(user) {
  if (!user) return 'unknown';
  if (!user.is_active) return 'inactive';
  if (user.status === 'active' || user.verified_at) return 'active';
  return 'waiting_code';
},

/**
 * Verify inbound message as access code for this phone.
 * DB-only — no workflow builder involvement.
 * waiting_code → active on success.
 */
tryUnlock(phone, codeInput) {
  const code = this.normalizeCode(codeInput);
  if (!code || code.length < 4) {
    return { ok: false, reason: 'invalid_input' };
  }

  const user = this.findByPhone(phone);
  if (!user || !user.is_active) {
    return { ok: false, reason: 'unknown_phone' };
  }

  if (user.status === 'active' || user.verified_at) {
    return { ok: true, user, reason: 'already_active' };
  }

  if (this.normalizeCode(user.access_code) !== code) {
    return { ok: false, reason: 'wrong_code', user };
  }

  db.prepare(
    `UPDATE access_users
     SET status = 'active',
         verified_at = datetime('now'),
         updated_at = datetime('now')
     WHERE id = ?`
  ).run(user.id);

  return { ok: true, user: this.get(user.id), reason: 'unlocked' };
},

create({ name, phone, access_code }) {
  let digits = digitsOnly(phone);
  const code = this.normalizeCode(access_code);
  const displayName = String(name || '').trim();
  if (!displayName) throw new Error('Name is required');
  if (!digits) throw new Error('Phone number is required');
  if (!code || code.length < 4) throw new Error('Access code must be at least 4 characters');

  if (digits.length === 10) digits = `91${digits}`;

  const result = db
    .prepare(
      `INSERT INTO access_users (name, phone, access_code, status)
       VALUES (?, ?, ?, 'waiting_code')`
    )
    .run(displayName, digits, code);
  return this.get(result.lastInsertRowid);
},

update(id, { name, phone, access_code, is_active, clear_verified }) {
  const current = this.get(id);
  if (!current) return null;
  let digits =
    phone !== undefined ? digitsOnly(phone) || current.phone : current.phone;
  if (phone !== undefined && digits && digits.length === 10) {
    digits = `91${digits}`;
  }
  const code =
    access_code !== undefined
      ? this.normalizeCode(access_code) || current.access_code
      : current.access_code;
  const displayName =
    name !== undefined ? String(name || '').trim() || current.name : current.name;

  db.prepare(
    `UPDATE access_users
     SET name = ?,
         phone = ?,
         access_code = ?,
         is_active = COALESCE(?, is_active),
         verified_at = CASE WHEN ? = 1 THEN NULL ELSE verified_at END,
         status = CASE WHEN ? = 1 THEN 'waiting_code' ELSE status END,
         updated_at = datetime('now')
     WHERE id = ?`
  ).run(
    displayName,
    digits,
    code,
    is_active ?? null,
    clear_verified ? 1 : 0,
    clear_verified ? 1 : 0,
    id
  );
  return this.get(id);
},

lock(phone) {
  const user = this.findByPhone(phone);
  if (user) {
    db.prepare(
      `UPDATE access_users
       SET verified_at = NULL,
           status = 'waiting_code',
           updated_at = datetime('now')
       WHERE id = ?`
    ).run(user.id);
    return;
  }
  const digits = digitsOnly(phone);
  db.prepare(
    `UPDATE access_users
     SET verified_at = NULL,
         status = 'waiting_code',
         updated_at = datetime('now')
     WHERE phone = ?`
  ).run(digits);
},

